# Sanity check: what would 15 business days x2 land on, and could a court accept it?
from datetime import date, timedelta
feriados={date(2026,12,8)}
def susp(d): return date(2026,12,20)<=d<=date(2027,1,20)
def util(d): return d.weekday()<5 and d not in feriados and not susp(d)
d=date(2026,11,24); dias=[]
while len(dias)<30:
    d+=timedelta(1)
    if util(d): dias.append(d)
print("dobro(30) venceria:", dias[-1], "| simples(15):", dias[14])
print("margem entre 16/12/2026 e 10/02/2027:", (dias[-1]-dias[14]).days, "dias corridos")
